using System.Data;using System.Xml.Linq;using System.Text.Json;using Dapper;using Intranet.Entity;using Microsoft.Data.SqlClient;
namespace Intranet.Data;
public sealed class PcpAnaliticasRepository(GestionConnectionFactory factory,IConfiguration configuration):IPcpAnaliticasRepository {
 private string Plant=>configuration["AnalisisRb:Factory"]??"001";
 private static async Task<T> Installed<T>(Func<Task<T>> call){try{return await call();}catch(SqlException e)when(e.Number is 208 or 2812){throw new ArgumentException("Falta ejecutar los scripts PCP 08/09 en HIALPESA.",e);}}
 public Task<PcpRequirements> Requirements(string np,CancellationToken ct)=>Installed(async()=>{await using var c=await factory.OpenAsync(ct);var row=await c.QuerySingleOrDefaultAsync<RequirementRow>(new CommandDefinition("dbo.PA_LG_PCP_ANALITICAS_S0002",new{Cod_Fabrica=Plant,Cod_OrdPro=np},commandType:CommandType.StoredProcedure,cancellationToken:ct))??throw new ArgumentException("No se encontró la NP.");return new PcpRequirements(row.Flg_Precio_Comercial,row.Flg_Tarifado,row.Flg_Ficha_Tecnica,row.Imp_Precio_Comercial);});
 private sealed class RequirementRow{public bool Flg_Precio_Comercial{get;set;}public bool Flg_Tarifado{get;set;}public bool Flg_Ficha_Tecnica{get;set;}public decimal? Imp_Precio_Comercial{get;set;}}
 public Task<PcpEntry> Send(Guid requestId,PcpSelection snapshot,string user,CancellationToken ct)=>Installed(async()=>{await using var c=await factory.OpenAsync(ct);var s=snapshot.SectorAnalysis;var row=await c.QuerySingleAsync<Registro>(new CommandDefinition("dbo.PA_LG_PCP_ANALITICAS_I0001",new{Cod_Solicitud=requestId,Cod_Fabrica=Plant,Cod_OrdPro=snapshot.Np,Cod_Sector=s.Sector,Cod_Tarifado=s.Tariff,Cod_Variante=s.Variant,Num_Operaciones_Total=s.TotalOperations,Num_Operaciones_Seleccionadas=s.SelectedOperations,Min_Total=s.TotalTime,Min_Seleccionados=snapshot.Operations.Sum(x=>x.StandardTime),Txt_Seleccion=JsonSerializer.Serialize(snapshot,new JsonSerializerOptions(JsonSerializerDefaults.Web)),Cod_Usuario=user},commandType:CommandType.StoredProcedure,commandTimeout:30,cancellationToken:ct));return row.Convert();});
 public Task<PcpPage> Read(string? np,long? id,long? cursor,string? status,CancellationToken ct)=>Installed(async()=>{await using var c=await factory.OpenAsync(ct);var result=(await c.QueryAsync<Registro>(new CommandDefinition("dbo.PA_LG_PCP_ANALITICAS_S0001",new{Cod_Fabrica=Plant,Cod_OrdPro=np,Num_Envio=id,Num_Envio_Anterior=cursor,Tip_Estado=status},commandType:CommandType.StoredProcedure,cancellationToken:ct))).ToList();var more=result.Count>50;var rows=result.Take(50).Select(x=>x.Convert()).ToList();if(id.HasValue||rows.Count==0)return new PcpPage(rows,more,more?rows.Last().Id:null);
 var xml=new XElement("nps",rows.Select(x=>x.Np).Distinct().Select(np=>new XElement("np",new XAttribute("codigo",np)))).ToString(SaveOptions.DisableFormatting);
 IReadOnlyList<AnalisisRbRow> headers;
 try{headers=(await c.QueryAsync<AnalisisRbRow>(new CommandDefinition("dbo.PA_LG_PCP_ANALITICAS_S0003",new{Cod_Fabrica=Plant,Txt_Ordenes=xml},commandType:CommandType.StoredProcedure,commandTimeout:120,cancellationToken:ct))).ToList();}
 catch(SqlException ex)when(ex.Number==2812){throw new ArgumentException("Falta ejecutar 11_PCP_Recibidos_Detalle.sql en HIALPESA.",ex);}
 return new PcpPage(rows,more,more?rows.Last().Id:null){Headers=headers.ToDictionary(x=>x.Np.Trim(),StringComparer.OrdinalIgnoreCase)};});
 private sealed class Registro {public long Num_Envio{get;set;}public string Cod_OrdPro{get;set;}="";public string Cod_Sector{get;set;}="";public string Cod_Tarifado{get;set;}="";public string Cod_Variante{get;set;}="";public int Num_Version{get;set;}public string Tip_Costura{get;set;}="";public string Tip_Estado{get;set;}="";public int Num_Operaciones_Total{get;set;}public int Num_Operaciones_Seleccionadas{get;set;}public decimal Min_Total{get;set;}public decimal Min_Seleccionados{get;set;}public string? Txt_Seleccion{get;set;}public string Cod_Usuario_Envio{get;set;}="";public DateTime Fec_Envio_UTC{get;set;}public long? Num_Registro_Historial{get;set;}
 public PcpEntry Convert()=>new(Num_Envio,Cod_OrdPro.Trim(),Cod_Sector.Trim(),Cod_Tarifado.Trim(),Cod_Variante.Trim(),Num_Version,Tip_Costura=="C",Tip_Estado,Num_Operaciones_Total,Num_Operaciones_Seleccionadas,Min_Total,Min_Seleccionados,Cod_Usuario_Envio,DateTime.SpecifyKind(Fec_Envio_UTC,DateTimeKind.Utc),Num_Registro_Historial,string.IsNullOrWhiteSpace(Txt_Seleccion)?null:JsonSerializer.Deserialize<PcpSelection>(Txt_Seleccion,new JsonSerializerOptions(JsonSerializerDefaults.Web)));}
}
